765 |     let mut compress = |buf: &[u8], in_end: usize, out_curr: &mut usize| {
766 |         let mut in_curr = 0;
767 |         while in_curr < in_end {
768 |             let word = fsst_unaligned_load_unchecked(buf[in_curr..].as_ptr());
769 |             let short_code = st.short_codes[(word & 0xFFFF) as usize];
770 |             let word_first_3_byte = word & 0xFFFFFF;
771 |             let idx = fsst_hash(word_first_3_byte) as usize & (FSST_HASH_TAB_SIZE - 1);
772 |             let s = st.hash_tab[idx];
773 |             out[*out_curr + 1] = word as u8; // speculatively write out escaped byte
774 |             let code = if s.icl < FSST_ICL_FREE && s.val == (word & (u64::MAX >> (s.icl & 0xFFFF)))
775 |             {
776 |                 (s.icl >> 16) as u16
777 |             } else {
778 |                 short_code
779 |             };
780 |             out[*out_curr] = code as u8;
781 |             in_curr += (code >> 12) as usize;
782 |             *out_curr += 1 + ((code & 256) >> 8) as usize;
783 |         }
