1298 |                 .is_none_or(|needed| needed > out_buf.len())
1299 |         {
1300 |             return Err(io::Error::new(
1301 |                 io::ErrorKind::InvalidInput,
1302 |                 "output buffer too small for FSST decoder",
1303 |             ));
1304 |         }
1305 | 
1306 |         // when decoder_switch_on is false, we make sure the out_buf is at least the same size of the in_buf,
1307 |         if !self.decoder_switch_on && in_buf.len() > out_buf.len() {
1308 |             return Err(io::Error::new(
1309 |                 io::ErrorKind::InvalidInput,
1310 |                 "output buffer too small for FSST decoder",
1311 |             ));
1312 |         }
1313 | 
1314 |         if in_offsets_buf.len() > out_offsets_buf.len() {
1315 |             return Err(io::Error::new(
1316 |                 io::ErrorKind::InvalidInput,
1317 |                 format!(
1318 |                     "output offsets buffer ({}) too small for FSST decoder (need at least {})",
1319 |                     out_offsets_buf.len(),
1320 |                     in_offsets_buf.len()
1321 |                 ),
1322 |             ));
1323 |         }
1324 |         let symbol_num = (st_info & 255) as u8;
1325 |         let mut pos = 8;
1326 |         for i in 0..symbol_num as usize {
1327 |             self.symbols[i] = fsst_unaligned_load_unchecked(symbol_table[pos..].as_ptr());
1328 |             pos += 8;
1329 |         }
1330 |         for i in 0..symbol_num as usize {
1331 |             let len = symbol_table[pos];
1332 |             if !(1..=MAX_SYMBOL_LENGTH as u8).contains(&len) {
1333 |                 return Err(io::Error::new(
1334 |                     io::ErrorKind::InvalidData,
1335 |                     format!(
1336 |                         "FSST symbol length at index {i} is {len}, expected 1..={MAX_SYMBOL_LENGTH}"
1337 |                     ),
1338 |                 ));
1339 |             }
1340 |             self.lens[i] = len;
1341 |             pos += 1;
1342 |         }
1343 |         Ok(())
1344 |     }
