1346 |     fn decompress(
1347 |         &mut self,
1348 |         in_buf: &[u8],
1349 |         in_offsets_buf: &[T],
1350 |         out_buf: &mut Vec<u8>,
1351 |         out_offsets_buf: &mut Vec<T>,
1352 |     ) -> io::Result<()> {
1353 |         if !self.decoder_switch_on {
1354 |             validate_offsets(in_offsets_buf, in_buf.len())?;
1355 |             out_buf.resize(in_buf.len(), 0);
1356 |             out_buf.copy_from_slice(in_buf);
1357 |             out_offsets_buf.resize(in_offsets_buf.len(), T::from_usize(0).unwrap());
1358 |             out_offsets_buf.copy_from_slice(in_offsets_buf);
1359 |             return Ok(());
1360 |         }
1361 |         let mut out_pos = 0;
1362 |         let mut out_offsets_len = 0;
1363 |         decompress_bulk(
1364 |             self,
1365 |             in_buf,
1366 |             in_offsets_buf,
1367 |             out_buf,
1368 |             out_offsets_buf,
1369 |             &mut out_pos,
1370 |             &mut out_offsets_len,
1371 |         )?;
1372 |         Ok(())
1373 |     }
1374 | }
