1376 | /// This is the public API for the FSST compression, when the in_buf is less than FSST_LEAST_INPUT_SIZE, we put the FSST_MAGIC header and then copy the input to the output
1377 | /// we check to make sure the out_buf's size is at least the same as the in_buf's size, otherwise Err is returned, this is actually
1378 | /// risky as in some randomly generated data, the output size can be larger than the input size.
1379 | /// the out_offsets_buf should be at least the same size as the in_offsets_buf, otherwise Err is returned
1380 | /// the symbol_table is used to store the symbol table created by `compression`, it's size should be FSST_SYMBOL_TABLE_SIZE
1381 | /// after compression, the first 64 bits of the output buffer is the fsst header:
1382 | /// from most significant bit to least significant bit:
1383 | /// FSST_MAGIC| encoder_switch |    suffix_lim | terminator | n_symbols
1384 | /// | 32-bits |         8 bits |        8 bits |     8 bits | 8 bits
1385 | /// then followed by the compressed data
1386 | ///
1387 | pub fn compress<T: OffsetSizeTrait>(
1388 |     symbol_table: &mut [u8],
1389 |     in_buf: &[u8],
1390 |     in_offsets_buf: &[T],
1391 |     out_buf: &mut Vec<u8>,
1392 |     out_offsets_buf: &mut Vec<T>,
1393 | ) -> io::Result<()> {
1394 |     FsstEncoder::new().compress(
1395 |         in_buf,
1396 |         in_offsets_buf,
1397 |         out_buf,
1398 |         out_offsets_buf,
1399 |         symbol_table,
1400 |     )?;
1401 |     Ok(())
1402 | }
1403 | // This is the public API for the FSST decompression, when the first 32 bits of in_buf is not the FSST_MAGIC, we know the input is not a
1404 | // valid FSST compressed data and return an error
1405 | // the following 32 bits after FSST_MAGIC contains information about FSST encoding, such as decoder_switch_on, suffix_lim, terminator, n_symbols
1406 | // when the decoder_switch_on is off in the in_buf header, `decompress` first make sure the out_buf is at least the same size as the in_buf, then simply copy the
1407 | // input data to the output
1408 | // when the decoder_switch_on is on, `decompress` first make sure the out_buf is at least 8 times the size of the in_buf, then start decoding the
1409 | // data using the symbol table. The 8x bound is required for correctness: a 1-byte code can expand to
1410 | // an 8-byte symbol, and the decode loop writes a full 8-byte word per code, so a smaller buffer can
1411 | // be written out of bounds.
1412 | // the out_offsets_buf should be at least the same size as the in_offsets_buf, otherwise an error is returned
1413 | // the symbol_table, compressed bytes, and offsets are untrusted: declared symbol lengths must be
1414 | // 1..=8 and offsets must be a non-decreasing sequence of values that fit in usize and lie within
1415 | // the compressed buffer. Corrupt input returns InvalidData instead of writing out of bounds.
1416 | // the symbol_table is the same symbol table created by `compression`
1417 | pub fn decompress<T: OffsetSizeTrait>(
1418 |     symbol_table: &[u8],
1419 |     in_buf: &[u8],
1420 |     in_offsets_buf: &[T],
1421 |     out_buf: &mut Vec<u8>,
1422 |     out_offsets_buf: &mut Vec<T>,
1423 | ) -> io::Result<()> {
1424 |     let mut decoder = FsstDecoder::new();
1425 |     decoder.init(
1426 |         symbol_table,
1427 |         in_buf,
1428 |         in_offsets_buf,
1429 |         out_buf,
1430 |         out_offsets_buf,
1431 |     )?;
1432 |     decoder.decompress(in_buf, in_offsets_buf, out_buf, out_offsets_buf)?;
1433 |     Ok(())
1434 | }
